def load_input(cid):
    return json.loads((INP / f"{cid}.json").read_text(encoding="utf-8"))

written = []
for cid in IDS:
    d = load_input(cid)
    if cid.startswith("LY-"):
        pred, basis_core, conf, cm, ru, disp, treason = LY[cid]
        trad_raw = d.get("tradition") or "liuyao"
        basis = f"tradition={trad_raw}\nsystems_used=六爻纳甲\n{basis_core}"
        trig = {"changed_main": cm, "reserve_used": ru, "disputed": disp, "reason": treason}
    elif cid.startswith("MH-"):
        pred, trad_raw, sysline, conf, extra = MH[cid]
        basis = f"tradition={trad_raw}\nsystems_used={sysline}\n{extra}"
        trig = {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}
    elif cid.startswith("MP-"):
        pred, conf, sysline = MP[cid]
        basis = f"tradition=modern_prediction\nsystems_used={sysline}\n输入卡无卦盘/牌面/命盘等盘面字段，亦无tradition字段；按SKILL路由无盘不造盘，不起卦不排盘，只据题面已载事实（候选人身份、时点、民调与连署等题面信息）作事件级预测。已载面表：主问面=本题所问胜负/前景（已断）；题面已载事件面与关系面均已并入prediction_text对应断语；应期面=投票日/事件时点题面已载（已断）。断项过闸：每条断项指代链指回题面人物/事件、触发为题面事实，已在prediction_text注依据；无盘面触发可指者已降为量级带/倾向表述。R61-REV1：应期主坐标为题面投票日（事件型既定坐标），复推路径为题面时点倒推选战窗口，二路同点；具体断项粒度核已在prediction_text末句注明。方向锁定：本核未改方向。"
        trig = {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}
    else:
        raise SystemExit(f"unknown prefix {cid}")
    obj = {"case_id": cid, "prediction_text": pred, "basis": basis, "confidence": conf, "trigger": trig}
    fp = OUT / f"{cid}.json"
    fp.write_text(json.dumps(obj, ensure_ascii=False, indent=1), encoding="utf-8")
    written.append(cid)

# validation: per-id exact open only (this batch)
total_bytes = 0; cm_c = ru_c = di_c = 0; trads = {}
for cid in IDS:
    fp = OUT / f"{cid}.json"
    assert fp.exists(), cid
    o = json.loads(fp.read_text(encoding="utf-8"))
    assert set(o.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, cid
    assert o["case_id"] == cid
    assert 0 <= o["confidence"] <= 1
    assert set(o["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
    assert all(isinstance(o["trigger"][k], bool) for k in ("changed_main","reserve_used","disputed"))
    total_bytes += fp.stat().st_size
    if cid.startswith("LY-"):
        cm_c += o["trigger"]["changed_main"]; ru_c += o["trigger"]["reserve_used"]; di_c += o["trigger"]["disputed"]
    first = o["basis"].splitlines()[0].replace("tradition=","")
    trads[first] = trads.get(first, 0) + 1
print(json.dumps({"count": len(IDS), "written": len(written), "total_bytes": total_bytes,
                  "ly_trigger": {"changed_main": cm_c, "reserve_used": ru_c, "disputed": di_c},
                  "traditions": trads}, ensure_ascii=False))
